import re

def parse_sensor_reading(reading):
    '''Parses a sensor reading string and returns a dict with temperature, humidity, and timestamp.'''
    result = {"temperature": None, "humidity": None, "timestamp": None}
    if not reading or not isinstance(reading, str):
        return result
    reading_str = reading.strip()
    if not reading_str:
        return result
    parts = reading_str.split("|")
    for part in parts:
        part = part.strip()
        if ":" not in part:
            continue
        key, value = part.split(":", 1)
        key = key.strip()
        value = value.strip()
        if key == "T":
            try:
                result["temperature"] = float(value)
            except (ValueError, TypeError):
                result["temperature"] = None
        elif key == "H":
            try:
                result["humidity"] = float(value)
            except (ValueError, TypeError):
                result["humidity"] = None
        elif key == "TS":
            if re.fullmatch(r"[+-]?\d+", value):
                try:
                    result["timestamp"] = int(value)
                except (ValueError, TypeError):
                    result["timestamp"] = None
            else:
                result["timestamp"] = None
    return result

